    public ApiRepository(Context c){context=c.getApplicationContext();shield=new YoruShield(context);}
    private synchronized void ensureBoot(){if(bootLoaded)return;bootLoaded=true;try{JSONObject boot=new JSONObject(readStream(context.getAssets().open("boot.json"),3*1024*1024));JSONArray rows=boot.optJSONArray("releases");for(int i=0;rows!=null&&i<rows.length();i++){Anime a=Anime.from(rows.getJSONObject(i));a.cached=true;if(a.id.equals("9542"))a.malId=52991;if(a.id.equals("9600"))a.malId=52299;if(a.id.equals("9555"))a.malId=54492;seed.add(a);known.put(a.key(),a);}}catch(Exception ignored){}try{JSONObject cs=new JSONObject(readStream(context.getAssets().open("counts.json"),100000));Iterator<String> it=cs.keys();while(it.hasNext()){String key=it.next();JSONObject row=cs.optJSONObject(key);long n=row==null?-1:row.optLong("value",-1);if(n>=0)counts.put(key,n);}}catch(Exception ignored){}}
    public long countOf(String source){ensureBoot();if("yoru".equals(source))return countOf("all");if("all".equals(source)){long sum=0;for(String s:REAL_SOURCES){Long n=counts.get(s);if(n!=null&&n>0)sum+=n;}return sum>0?sum:-1;}Long n=counts.get(source);return n==null?-1:n;}
